def simulate_race(schedule, initial_value=0):
    shared = initial_value
    thread_local = {}
    for thread_id, step in schedule:
        if step == 'read':
            thread_local[thread_id] = shared
        elif step == 'write':
            shared = thread_local[thread_id] + 1
    return shared

